// 자동 생성 파일: node tools/build-wasm.js (원본 wasm/src/lib.rs). 직접 고치지 않는다.
// js/solver.js의 search를 WebAssembly로 돌린다. Node는 동기로, 브라우저는 비동기로 준비하며 준비 전에는 JS 탐색을 쓴다.
(function (root) {
  'use strict';
  const MH = (root.MH = root.MH || {});
  const B64 = '';
  const state = (MH.wasmSearch = { exports: null, error: null, bytes: 89330 });
  if (typeof WebAssembly === 'undefined') { state.error = new Error('WebAssembly 없음'); return; }
  const bytes = typeof Buffer !== 'undefined' ? new Uint8Array(Buffer.from(B64, 'base64')) : Uint8Array.from(atob(B64), (ch) => ch.charCodeAt(0));
  if (typeof window === 'undefined') {
    try { state.exports = new WebAssembly.Instance(new WebAssembly.Module(bytes)).exports; } catch (e) { state.error = e; }
  } else {
    WebAssembly.instantiate(bytes).then((res) => { state.exports = res.instance.exports; }, (e) => { state.error = e; });
  }
})(typeof window !== 'undefined' ? window : globalThis);
